def sum_of_digits(numbers):
    def compute_digit_sum(num):
        # Convert the number to a positive integer and compute the sum of its digits
        num = abs(num)  # Handle negative numbers
        return sum(int(digit) for digit in str(num))

    # Flatten the list if it contains nested lists and filter valid integers
    flattened_numbers = []
    for item in numbers:
        if isinstance(item, list):
            flattened_numbers.extend(item)
        elif isinstance(item, int):
            flattened_numbers.append(item)

    # Compute the sum of digits for each valid number
    return sum(compute_digit_sum(num) for num in flattened_numbers if isinstance(num, int))

# Example usage:
assert sum_of_digits([10, 2, 56]) == 14
assert sum_of_digits([[10, 20, 4, 5, 'b', 70, 'a']]) == 19
assert sum_of_digits([123, [45, 6], 'invalid', 789]) == 45
assert sum_of_digits([10, 20, -4, 5, -70]) == 19
