def max_Product(arr):
    if len(arr) < 2:
        return None  # Not enough elements for a pair

    # Initialize variables to track the two largest and two smallest numbers
    max1 = max2 = float('-inf')
    min1 = min2 = float('inf')

    # Iterate through the array to find the two largest and two smallest numbers
    for num in arr:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Compare the products of the two largest and two smallest numbers
    if max1 * max2 >= min1 * min2:
        return (max2, max1) if max2 <= max1 else (max1, max2)  # Return the pair with the highest product in ascending order
    else:
        return (min1, min2) if min1 <= min2 else (min2, min1)  # Return the pair with the highest product in ascending order

# Example test cases
assert max_Product([1, 2, 3, 4, 7, 0, 8, 4]) == (7, 8)
assert max_Product([0, -1, -2, -4, 5, 0, -6]) == (-6, -4)
```

