def cal_sum(n):
    def perrin_number(k):
        if k == 0:
            return 3
        elif k == 1:
            return 0
        elif k == 2:
            return 2
        else:
            a, b, c = 3, 0, 2
            for _ in range(3, k + 1):
                a, b, c = b, c, a + b
            return c

    return sum(perrin_number(i) for i in range(n + 1))

# Example test
assert cal_sum(9) == 49
